  aspect: f32,
  angle: f32,
  trapLayerBase: f32, // -1 when no true-orbit payload is allocated
  rawOriginX: f32,    // toroidal origin of the raw texture (pan by offset)
  rawOriginY: f32,
  tileOriginX: f32,
  tileOriginY: f32,
  neutralSide: f32,
